// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }
    function testFuzz_property(bytes memory data) public {
        Recorder recorder = new Recorder();
        c.forward(address(recorder), data);
        assertTrue(recorder.callCount() == 1 && keccak256(recorder.lastData()) == keccak256(data));
    }
}

contract Recorder {
    uint256 public callCount;
    bytes public lastData;
    fallback() external payable {
        callCount++;
        lastData = msg.data;
    }
}
